@push('scripts')<script>
const boms = {{ Illuminate\Support\Js::from($bomWizardData) }};
const workers = {{ Illuminate\Support\Js::from($workerWizardData) }};
let step=0, assignments=[], selectedBom=null;
const product=document.getElementById('product_id'),variant=document.getElementById('variant_id'),bomSelect=document.getElementById('bom_id'),qty=document.getElementById('planned_quantity');
function option(value,label){return `<option value="${value}">${label}</option>`} function workerOptions(){return '<option value="">اختر العامل</option>'+workers.map(w=>option(w.id,`${w.name} (${w.code})`)).join('')}
function refreshVariants(){const list=[...new Map(boms.filter(b=>String(b.product_id)===product.value).map(b=>[b.variant_id,b])).values()];variant.innerHTML='<option value="">اختر</option>'+list.map(b=>option(b.variant_id,b.variant)).join('');bomSelect.innerHTML='<option value="">اختر</option>';selectedBom=null;renderAll()}
function refreshBoms(){const list=boms.filter(b=>String(b.variant_id)===variant.value);bomSelect.innerHTML='<option value="">اختر</option>'+list.map(b=>option(b.id,`${b.number} / v${b.version}`)).join('');selectedBom=null;renderAll()}
function chooseBom(){selectedBom=boms.find(b=>String(b.id)===bomSelect.value);assignments=[];(selectedBom?.operations||[]).forEach(op=>assignments.push({key:crypto.randomUUID(),operation_id:op.id,worker_id:'',quantity:'',notes:''}));renderAll()}
function requirements(){const amount=+qty.value||0;return (selectedBom?.items||[]).map(i=>({...i,required:+((i.quantity/selectedBom.basis)*amount).toFixed(3)}))}
function renderRequirements(){const rows=requirements();document.getElementById('requirements-body').innerHTML=rows.length?rows.map(i=>`<tr><td>${i.name}</td><td>${i.required.toFixed(3)} ${i.unit}</td><td>${i.available.toFixed(3)}</td><td><span class="badge bg-${i.available>=i.required?'success':'danger'}">${i.available>=i.required?'متاح':'غير كافٍ'}</span></td></tr>`).join(''):'<tr><td colspan="4" class="text-center text-muted">حدد BOM والكمية أولاً.</td></tr>'}
function addAssignment(opId){assignments.push({key:crypto.randomUUID(),operation_id:opId,worker_id:'',quantity:'',notes:''});renderAssignments()}
function removeAssignment(key){assignments=assignments.filter(a=>a.key!==key);renderAssignments()}
function setAssignment(key,field,value){const a=assignments.find(x=>x.key===key);if(a)a[field]=value}
function renderAssignments(){const target=document.getElementById('operations-assignments');if(!selectedBom){target.innerHTML='<div class="alert alert-light">حدد BOM أولاً.</div>';return}target.innerHTML=selectedBom.operations.map(op=>{const rows=assignments.filter(a=>a.operation_id===op.id);const total=rows.reduce((s,a)=>s+(+a.quantity||0),0);return `<div class="card mb-3"><div class="card-header bg-white d-flex justify-content-between"><strong>${op.sequence}. ${op.name}</strong><span>المسند: <b>${total.toFixed(3)}</b> / ${(+qty.value||0).toFixed(3)} <button type="button" class="btn btn-sm btn-outline-primary ms-2" onclick="addAssignment(${op.id})">عامل إضافي</button></span></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>العامل</th><th>الكمية</th><th>ملاحظات</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><select class="form-select" onchange="setAssignment('${a.key}','worker_id',this.value)">${workerOptions().replace(`value="${a.worker_id}"`,`value="${a.worker_id}" selected`)}</select></td><td><input class="form-control" type="number" step="0.001" min="0.001" value="${a.quantity}" onchange="setAssignment('${a.key}','quantity',this.value);renderAssignments()"></td><td><input class="form-control" value="${a.notes}" onchange="setAssignment('${a.key}','notes',this.value)"></td><td><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeAssignment('${a.key}')">حذف</button></td></tr>`).join('')}</tbody></table></div></div>`}).join('')}
function renderAllocations(){const target=document.getElementById('allocation-container'),req=requirements();if(!selectedBom){target.innerHTML='';return}target.innerHTML=`<div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>العملية / العامل</th>${req.map(i=>`<th>${i.name}<small class="d-block text-muted">الإجمالي ${i.required.toFixed(3)}</small></th>`).join('')}</tr></thead><tbody>${assignments.map((a,index)=>{const op=selectedBom.operations.find(o=>o.id===a.operation_id),worker=workers.find(w=>String(w.id)===String(a.worker_id));return `<tr><td>${op?.name||''}<br><strong>${worker?.name||'لم يحدد'}</strong> — ${(+a.quantity||0).toFixed(3)}${hiddenAssignment(a,index)}</td>${req.map(i=>{const firstOp=op?.sequence===Math.min(...selectedBom.operations.map(x=>x.sequence));const suggested=firstOp?i.required*((+a.quantity||0)/(+qty.value||1)):0;return `<td><input name="assignments[${index}][materials][${i.id}][allocated_quantity]" class="form-control" type="number" min="0" step="0.001" value="${suggested.toFixed(3)}"></td>`}).join('')}</tr>`}).join('')}</tbody></table></div>`}
function hiddenAssignment(a,index){return `<input type="hidden" name="assignments[${index}][bom_operation_id]" value="${a.operation_id}"><input type="hidden" name="assignments[${index}][worker_id]" value="${a.worker_id}"><input type="hidden" name="assignments[${index}][assigned_quantity]" value="${a.quantity}"><input type="hidden" name="assignments[${index}][notes]" value="${a.notes.replaceAll('"','&quot;')}">`}
function renderAll(){renderRequirements();renderAssignments()} product.onchange=refreshVariants;variant.onchange=refreshBoms;bomSelect.onchange=chooseBom;qty.oninput=renderAll;
function showStep(n){step=n;document.querySelectorAll('.wizard-step').forEach(x=>x.classList.toggle('active',+x.dataset.step===step));document.querySelectorAll('.step-pill').forEach(x=>x.classList.toggle('active',+x.dataset.step===step));document.getElementById('prev-step').disabled=step===0;document.getElementById('next-step').classList.toggle('d-none',step===3);document.getElementById('submit-order').classList.toggle('d-none',step!==3);if(step===3)renderAllocations()}
document.getElementById('next-step').onclick=()=>showStep(Math.min(3,step+1));document.getElementById('prev-step').onclick=()=>showStep(Math.max(0,step-1));
</script>@endpush
